geometry_msgs::Point transformPoint(const geometry_msgs::Point& p, const tf::Transform& tf)
{
  // convert to tf msg
  tf::Point tf_point;
  tf::pointMsgToTF(p, tf_point);

  // apply transform
  tf_point = tf * tf_point;

  // convert to ros msg
  geometry_msgs::Point ros_point;
  tf::pointTFToMsg(tf_point, ros_point);

  return ros_point;

