{
  EdgeContainer::const_iterator lower = lower_bound(_activeEdges.begin(), _activeEdges.end(), e, EdgeIDCompare());
  if (lower == _activeEdges.end())
    return _activeEdges.end();
  if ((*lower) == e)
    return lower;
  return _activeEdges.end();

