OpenGlMatrix OpenGlMatrix::RotateZ(GLprecision theta_rad)
{
    OpenGlMatrix mat;
    mat.SetIdentity();
    const GLprecision costh = cos(theta_rad);
    const GLprecision sinth = sin(theta_rad);
    mat(0, 0) = costh;
    mat(0, 1) = -sinth;
    mat(1, 0) = sinth;
    mat(1, 1) = costh;
    return mat;

