int AisanStopLineFileReader::ReadAllData(vector<AisanStopLine>& data_list)
{
	data_list.clear();
	AisanStopLine data;
	//double logTime = 0;
	int count = 0;
	while(ReadNextLine(data))
	{
		data_list.push_back(data);
		count++;
	}
	return count;

