	a = fabs(a - coarse_angle);
	if (a > 180)
		a = fabs(a - 360);
	double d = hypot(p1.bx - coarse_p1.bx, p1.ly - coarse_p1.ly);
	double s = a + d;
	if (s <= score) {
		nearest_point = p1;
		score = s;
	}
}

return nearest_point;

