int AisanWayareaFileReader::ReadAllData(vector<AisanWayarea>& data_list)
{
	data_list.clear();
	AisanWayarea data;
	//double logTime = 0;
	int count = 0;
	while(ReadNextLine(data))
	{
		data_list.push_back(data);
		count++;
	}
	return count;
}

//Data Conn
bool AisanDataConnFileReader::ReadNextLine(DataConn& data)
{
	vector<vector<string> > lineData;
	if(ReadSingleLine(lineData))
	{
		if(lineData.size()==0) return false;
		if(lineData.at(0).size() < 4) return false;

	printInfoMessage("SopasBase::receiveAnswer_CoLa_A: entering function.", m_beVerbose);

	SopasCommand receivedCommand;
	std::string rxData;
	if (timeout == 0)
	{
		timeout = 1; // Check at least once
	}

	// Check until number of cycles reaches timeout
	for (UINT32 i = 0; i < timeout; i++)
	{
		// Secure against read thread
		{
			ScopedLock lock(&m_receiveDataMutex);
			if (m_numberOfBytesInResponseBuffer > 0)
