  void Microstrain::ahrs_packet_callback(void *user_ptr, u8 *packet, u16 packet_size, u8 callback_type)
  {
    mip_field_header *field_header;
    u8               *field_data;
    u16              field_offset = 0;

ros::Publisher          initialpose_pub_;
ros::Publisher          overlay_info_text_pub_;
ros::Publisher			ndt_status_pub_;
ros::Time               last_prediction_time_;

double                  last_score_;
double                  current_score_;
double                  score_delta_threshold_;
double                  score_delta_;
int                     iteration_threshold_warning_;
int                     iteration_threshold_stop_;
double                  fatal_time_threshold_;
ndt_status              ndt_status_;

int                     iteration_count_;
bool                    gnss_pose_available_;
bool                    initialized_;
int                     min_stable_samples_;

cv::Mat imgHsv, V;
cv::cvtColor(colorInput, imgHsv, CV_BGR2HSV);
cv::extractChannel(imgHsv, V, 2);
// 2. Normalize V
V.convertTo(V, CV_32F);
V /= 255.0;
// Sum all elements of V per column
cv::Mat tv = cv::Mat::zeros(V.cols, 1, CV_32F);
for (int i=0; i<V.cols; i++) {
	tv.at<float>(i) = cv::sum(V.col(i))[0];
}
tv /= (float)V.rows;
// Count number of columns that are out of range
const float th = 0.1;
int nc = 0;
for (int i=0; i<V.cols; i++) {
	if (tv.at<float>(i) >= 1.0-th)
		nc += 1;
}
// done
if (nc < 2)
	return -1;

