}

/*clipping*/
if (x < 1 || x >= ndmap->x)
  return 0;
if (y < 1 || y >= ndmap->y)
  return 0;
if (z < 1 || z >= ndmap->z)
  return 0;

/*select root ND*/
ndp[0] = ndmap->nd + (int)x * ndmap->to_x + (int)y * ndmap->to_y + (int)z;
ndp[1] = ndp[0] - ndmap->to_x;
ndp[2] = ndp[0] - ndmap->to_y;
ndp[4] = ndp[0] - 1;
ndp[3] = ndp[2] - ndmap->to_x;
ndp[5] = ndp[4] - ndmap->to_x;
ndp[6] = ndp[4] - ndmap->to_y;
ndp[7] = ndp[3] - 1;

