		UtilityHNS::UtilityH::GetTickCount(m_TrackTimer);
	}

	m_DetectedObjects = obj_list;

	if(type == ASSOCIATE_ONLY)
	{
		AssociateOnly();
	}
	else if (type == SIMPLE_TRACKER)
	{
		AssociateSimply();
	}
	else
	{
		//AssociateAndTrack();
		AssociateDistanceOnlyAndTrack();
		CleanOldTracks();
	}

	m_PrevState = currPose;
}

