bool EdgeSim3ProjectXYZ::read(std::istream& is)
{
  for (int i=0; i<2; i++)
  {
    is >> _measurement[i];
  }

  for (int i=0; i<2; i++)
    for (int j=i; j<2; j++) {
is >> information()(i,j);
    if (i!=j)
      information()(j,i)=information()(i,j);
  }
  return true;
}

