	m_bUseCenterOnly = true;
	m_bFirstCall = true;
	m_nMinTrustAppearances = 5;
	m_Horizon = 100.0;
	m_CirclesResolution = 5.0;
	UtilityHNS::UtilityH::GetTickCount(m_TrackTimer);
}

void SimpleTracker::InitSimpleTracker()
{
	UtilityHNS::UtilityH::GetTickCount(m_TrackTimer);
	InitializeInterestRegions(m_InterestRegions);
}

SimpleTracker::~SimpleTracker()
{
	for(unsigned int i = 0; i < m_InterestRegions.size(); i++)
	{
		delete m_InterestRegions.at(i);
	}
	m_InterestRegions.clear();

	for(unsigned int i = 0; i < m_Tracks.size(); i++)
	{
		delete m_Tracks.at(i);
	}
	m_Tracks.clear();

}

void SimpleTracker::InitializeInterestRegions(std::vector<InterestCircle*>& regions)
{
	//initialize interest regions
	double next_raduis = m_CirclesResolution;
	double next_foget_time = m_MaxKeepTime;
	while(1)
	{
		InterestCircle* pCir = new InterestCircle(regions.size()+1);
		if(regions.size() == 0)
		{
			pCir->radius = next_raduis;
			pCir->forget_time = next_foget_time;
			regions.push_back(pCir);
			std::cout << "Region No: " << regions.size() << ", Radius: " << pCir->radius << ", F time: " << pCir->forget_time << std::endl;
		}
		else
		{
			pCir->radius = next_raduis;
			pCir->forget_time = next_foget_time;
			regions.push_back(pCir);

			std::cout << "Region No: " << regions.size() << ", Radius: " << pCir->radius << ", F time: " << pCir->forget_time << std::endl;
		}

		if(next_raduis >= m_Horizon)
			break;

		next_raduis += next_raduis * 0.8;
		if(next_raduis > m_Horizon)
			next_raduis = m_Horizon;
		next_foget_time -= next_foget_time * 0.25;
		if(next_foget_time < 0.1)
			next_foget_time = 0.1;
	}
}

void SimpleTracker::DoOneStep(const WayPoint& currPose, const std::vector<DetectedObject>& obj_list, const TRACKING_TYPE& type)
{
	if(!m_bFirstCall)

    astar_planner::getWaveFrontNode(-1, 1, std::hypot(resolution, resolution)),
    astar_planner::getWaveFrontNode(1, 1, std::hypot(resolution, resolution)),
    astar_planner::getWaveFrontNode(-1, -1, std::hypot(resolution, resolution)),
    astar_planner::getWaveFrontNode(1, -1, std::hypot(resolution, resolution)),
  };

  // Get start index
  int start_index_x;
  int start_index_y;
  int start_index_theta;
  poseToIndex(start_pose_local_.pose, &start_index_x, &start_index_y, &start_index_theta);

  // Whether the robot can reach goal
  bool reachable = false;

  // Start wavefront search
  while (!qu.empty())
  {
    WaveFrontNode ref = qu.front();
    qu.pop();

    WaveFrontNode next;
    for (const auto &u : updates)
    {
      next.index_x = ref.index_x + u.index_x;
      next.index_y = ref.index_y + u.index_y;

      // out of range OR already visited OR obstacle node
      if (isOutOfRange(next.index_x, next.index_y) || nodes_[next.index_y][next.index_x][0].hc > 0 ||
          nodes_[next.index_y][next.index_x][0].status == STATUS::OBS)
        continue;

      // Take the size of robot into account
      if (detectCollisionWaveFront(next))
        continue;

      // Check if we can reach from start to goal
      if (next.index_x == start_index_x && next.index_y == start_index_y)
        reachable = true;

      // Set wavefront heuristic cost
      next.hc = ref.hc + u.hc;
      nodes_[next.index_y][next.index_x][0].hc = next.hc;

      qu.push(next);
    }
  }

  // End of search
  return reachable;
}

// Simple collidion detection for wavefront search
bool AstarSearch::detectCollisionWaveFront(const WaveFrontNode &ref)
{
  // Define the robot as square
  static double half = robot_width_ / 2;
  double robot_x = ref.index_x * map_info_.resolution;
  double robot_y = ref.index_y * map_info_.resolution;

  for (double y = half; y > -1.0 * half; y -= map_info_.resolution)
  {
    for (double x = -1.0 * half; x < half; x += map_info_.resolution)
    {
      int index_x = (robot_x + x) / map_info_.resolution;
      int index_y = (robot_y + y) / map_info_.resolution;

      if (isOutOfRange(index_x, index_y))
        return true;

      if (nodes_[index_y][index_x][0].status == STATUS::OBS)
        return true;
    }
  }

  return false;
}

