void publish_msg(sensor_msgs::Image* p_image_raw_buf, sensor_msgs::PointCloud2* p_points_raw_buf)
{
    ROS_INFO("publish");
    image_raw_pub.publish(*p_image_raw_buf);
    points_raw_pub.publish(*p_points_raw_buf);
}

bool publish() {
    if (buf_flag) {
        pthread_mutex_lock(&mutex);

        //image_raw is empty
        if (image_raw_ringbuf.begin() == image_raw_ringbuf.end()) {
            pthread_mutex_unlock(&mutex);
            ROS_INFO("image_raw ring buffer is empty");
            return false;
        }

        //points_raw is empty
        if (points_raw_ringbuf.begin() == points_raw_ringbuf.end()) {
            pthread_mutex_unlock(&mutex);
            ROS_INFO("points_raw ring buffer is empty");
            return false;
        }

        // image_raw > points_raw
        if (get_time(&(image_raw_ringbuf.front().header)) >= get_time(&(points_raw_ringbuf.front().header))) {
            p_points_raw_buf = &(points_raw_ringbuf.front());
            boost::circular_buffer<sensor_msgs::Image>::iterator it = image_raw_ringbuf.begin();
            if (image_raw_ringbuf.size() == 1) {
                p_image_raw_buf = &*it;
                publish_msg(p_image_raw_buf, p_points_raw_buf);
                pthread_mutex_unlock(&mutex);
                return true;
            } else {
                for (it++; it != image_raw_ringbuf.end(); it++) {
                    if (fabs_time_diff(&(points_raw_ringbuf.front().header), &((it-1)->header))
                        < fabs_time_diff(&(points_raw_ringbuf.front().header), &(it->header))) {
                        p_image_raw_buf = &*(it-1);
                        break;
                    }
                }
                if (it == image_raw_ringbuf.end()) {
                    p_image_raw_buf = &(image_raw_ringbuf.back());
                }
            }
        }
        // image_raw < points_raw
        else {
            p_image_raw_buf = &(image_raw_ringbuf.front());
            boost::circular_buffer<sensor_msgs::PointCloud2>::iterator it = points_raw_ringbuf.begin();
            if (points_raw_ringbuf.size() == 1) {
                p_points_raw_buf = &*it;
                publish_msg(p_image_raw_buf, p_points_raw_buf);
                pthread_mutex_unlock(&mutex);
                return true;
            }

            for (it++; it != points_raw_ringbuf.end(); it++) {
                if (fabs_time_diff(&(image_raw_ringbuf.front().header), &((it-1)->header))
                    < fabs_time_diff(&(image_raw_ringbuf.front().header), &(it->header))) {
                    p_points_raw_buf = &*(it-1);
                    break;
                }
            }

            if (it == points_raw_ringbuf.end()) {
                p_points_raw_buf = &(points_raw_ringbuf.back());
            }
        }
        publish_msg(p_image_raw_buf, p_points_raw_buf);

    pthread_mutex_unlock(&mutex);
}

void current_pose_callback(const geometry_msgs::PoseStamped::ConstPtr& current_pose_msg) {
    pthread_mutex_lock(&mutex);
    current_pose_ringbuf.push_front(*current_pose_msg);
    //image_obj_tracked is empty
    if (image_obj_tracked_ringbuf.begin() == image_obj_tracked_ringbuf.end()) {
        ROS_INFO("image_obj_tracked ring buffer is empty");
        pthread_mutex_unlock(&mutex);
        return;
    }

    buf_flag = true;

    // image_obj_tracked > current_pose
    if (get_time(&(image_obj_tracked_ringbuf.front().header)) >= get_time(&(current_pose_ringbuf.front().header))) {
        current_pose_buf = current_pose_ringbuf.front();
        boost::circular_buffer<autoware_msgs::ImageObjTracked>::iterator it = image_obj_tracked_ringbuf.begin();
        if (image_obj_tracked_ringbuf.size() == 1) {
            image_obj_tracked_buf = *it;
            pthread_mutex_unlock(&mutex);
            pthread_mutex_lock(&mutex);
            if (obj_label_flag == true) {
                publish();
            }
            pthread_mutex_unlock(&mutex);
            return;
        } else {
            for (it++; it != image_obj_tracked_ringbuf.end(); it++) {
                if (fabs_time_diff(&(current_pose_ringbuf.front().header), &((it-1)->header))
                    < fabs_time_diff(&(current_pose_ringbuf.front().header), &(it->header))) {
                    image_obj_tracked_buf = *(it-1);
                    break;
                }
            }
            if (it == image_obj_tracked_ringbuf.end()) {
                image_obj_tracked_buf = image_obj_tracked_ringbuf.back();
            }
        }

    } else {
        image_obj_tracked_buf = image_obj_tracked_ringbuf.front();
        boost::circular_buffer<geometry_msgs::PoseStamped>::iterator it = current_pose_ringbuf.begin();
        if (current_pose_ringbuf.size() == 1) {
            current_pose_buf = *it;
            pthread_mutex_unlock(&mutex);
            pthread_mutex_lock(&mutex);
            if (obj_label_flag == true) {
                publish();
            }
            pthread_mutex_unlock(&mutex);
            return;
        }

        for (it++; it != current_pose_ringbuf.end(); it++) {
            if (fabs_time_diff(&(image_obj_tracked_ringbuf.front().header), &((it-1)->header))
                < fabs_time_diff(&(image_obj_tracked_ringbuf.front().header), &(it->header))) {
                current_pose_buf = *(it-1);
                break;
            }
        }

        if (it == current_pose_ringbuf.end()) {
            current_pose_buf = current_pose_ringbuf.back();
        }
    }
    pthread_mutex_unlock(&mutex);

		particleList.resize(numberOfParticle);
//		std::fill(particleList.begin(), particleList.end(), Particle<state>(stateInitializer));
		srand(time(0));
	}

	void initializeParticles ()
	{
		for (Particle<State> &particle: particleList) {
			particle.current = vehicle.initializeParticleState();
			particle.previous = vehicle.initializeParticleState();
		}
	}

	inline void update (const MotionCtrl &control, const vector<Observation> &observationList)
	{
		// Prediction
		for (Particle<State> &p: particleList) {
			p.current = vehicle.motionModel (p.previous, control);
			p.swapState();
		}

		if (observationList.size()==0)
			return;

		// Importance factor
		double w_all = 0;
		for (Particle<State> &p: particleList) {
			p.weight = vehicle.measurementModel (p.current, observationList);
			w_all += p.weight;
		}

		// Resampling
		double r = frandom() / (double)numberOfParticle;
		int i = 0;
		double c = particleList[0].weight / w_all;

		for (int p=0; p<numberOfParticle; p++) {
			double U = r + p/((double)numberOfParticle);
			while (U > c) {
				i += 1;
				c += particleList[i].weight / w_all;
			}
			particleList[p].current = particleList[i].previous;
		}

		for (Particle<State> &particle: particleList) {
			particle.swapState();
		}
	}


	inline vector<State> getStates ()
	{
		vector<State> states;
		states.reserve(numberOfParticle);

		for (Particle<State> &p: particleList) {
			states.push_back(p.current);
		}

		return states;
	}


	inline void getStates (vector<State*> &statePtrList)
	{
		for (int i=0; i<particleList.size(); i++) {
			Particle<State> &pt = particleList[i];
			statePtrList[i] = &(pt.current);
		}
	}


	int getNumberOfParticles () const { return numberOfParticle; }

	Particle<State> &getParticle(int num)
	{
		return particleList[num];
	}


	vector < Particle<State> > &getParticleList () const
	{ return particleList; }


//	virtual ~ParticleFilter();

protected:
	VehicleBase<State, Observation, MotionCtrl> &vehicle;
	int numberOfParticle;
	vector < Particle<State> > particleList;

info.iFront = GetClosestNextPointIndexFast(_trajectory, p, prevIndex);
if(info.iFront > 0)
	info.iBack = info.iFront -1;
else
	info.iBack = 0;

if(info.iFront == 0)
{
	p0 = _trajectory.at(info.iFront);
	p1 = _trajectory.at(info.iFront+1);
}
else if(info.iFront > 0 && info.iFront < _trajectory.size()-1)
{
	p0 = _trajectory.at(info.iFront-1);
	p1 = _trajectory.at(info.iFront);
}
else
{
	p0 = _trajectory.at(info.iFront-1);
	p1 = WayPoint((p0.pos.x+_trajectory.at(info.iFront).pos.x)/2.0, (p0.pos.y+_trajectory.at(info.iFront).pos.y)/2.0, (p0.pos.z+_trajectory.at(info.iFront).pos.z)/2.0, p0.pos.a);
}

WayPoint prevWP = p0;
Mat3 rotationMat(-p1.pos.a);
Mat3 translationMat(-p.pos.x, -p.pos.y);
Mat3 invRotationMat(p1.pos.a);
Mat3 invTranslationMat(p.pos.x, p.pos.y);

p0.pos = translationMat*p0.pos;
p0.pos = rotationMat*p0.pos;

p1.pos = translationMat*p1.pos;
p1.pos = rotationMat*p1.pos;

double m = (p1.pos.y-p0.pos.y)/(p1.pos.x-p0.pos.x);
info.perp_distance = p1.pos.y - m*p1.pos.x; // solve for x = 0

if(std::isnan(info.perp_distance) || std::isinf(info.perp_distance)) info.perp_distance = 0;

info.to_front_distance = fabs(p1.pos.x); // distance on the x axes

info.perp_point = p1;
info.perp_point.pos.x = 0; // on the same y axis of the car
info.perp_point.pos.y = info.perp_distance; //perp distance between the car and the _trajectory

info.perp_point.pos = invRotationMat  * info.perp_point.pos;
info.perp_point.pos = invTranslationMat  * info.perp_point.pos;

info.from_back_distance = hypot(info.perp_point.pos.y - prevWP.pos.y, info.perp_point.pos.x - prevWP.pos.x);

info.angle_diff = UtilityH::AngleBetweenTwoAnglesPositive(p1.pos.a, p.pos.a)*RAD2DEG;

info.bAfter = false;
info.bBefore = false;

if(info.iFront == 0)
{
	info.bBefore = true;
}
else if(info.iFront == _trajectory.size()-1)
{
	int s = _trajectory.size();
	double angle_befor_last = UtilityH::FixNegativeAngle(atan2(_trajectory.at(s-2).pos.y - _trajectory.at(s-1).pos.y, _trajectory.at(s-2).pos.x - _trajectory.at(s-1).pos.x));
	double angle_from_perp = UtilityH::FixNegativeAngle(atan2(info.perp_point.pos.y - _trajectory.at(s-1).pos.y, info.perp_point.pos.x - _trajectory.at(s-1).pos.x));
	double diff_last_perp = UtilityH::AngleBetweenTwoAnglesPositive(angle_befor_last, angle_from_perp);
	info.after_angle = diff_last_perp;
	if(diff_last_perp > M_PI_2)
	{
		info.bAfter = true;

TrajectoryCost TrajectoryDynamicCosts::DoOneStep(const vector<vector<vector<WayPoint> > >& rollOuts,
		const vector<vector<WayPoint> >& totalPaths, const WayPoint& currState, const int& currIndex,
		const int& currLaneIndex,
		const PlanningParams& params, const CAR_BASIC_INFO& carInfo, const VehicleState& vehicleState,
		const std::vector<PlannerHNS::DetectedObject>& obj_list)
{
	TrajectoryCost bestTrajectory;
	bestTrajectory.bBlocked = true;
	bestTrajectory.closest_obj_distance = params.horizonDistance;
	bestTrajectory.closest_obj_velocity = 0;
	bestTrajectory.index = -1;

	if(!ValidateRollOutsInput(rollOuts) || rollOuts.size() != totalPaths.size()) return bestTrajectory;

	if(m_PrevCostIndex == -1)
		m_PrevCostIndex = params.rollOutNumber/2;

	m_TrajectoryCosts.clear();

	for(unsigned int il = 0; il < rollOuts.size(); il++)
	{
		if(rollOuts.at(il).size()>0 && rollOuts.at(il).at(0).size()>0)
		{
			vector<TrajectoryCost> costs = CalculatePriorityAndLaneChangeCosts(rollOuts.at(il), il, params);
			m_TrajectoryCosts.insert(m_TrajectoryCosts.end(), costs.begin(), costs.end());
		}
	}

	CalculateTransitionCosts(m_TrajectoryCosts, currIndex, params);


	WayPoint p;
	m_AllContourPoints.clear();
	for(unsigned int io=0; io<obj_list.size(); io++)
	{
		for(unsigned int icon=0; icon < obj_list.at(io).contour.size(); icon++)
		{
			p.pos = obj_list.at(io).contour.at(icon);
			p.v = obj_list.at(io).center.v;
			p.id = io;
			p.cost = sqrt(obj_list.at(io).w*obj_list.at(io).w + obj_list.at(io).l*obj_list.at(io).l);
			m_AllContourPoints.push_back(p);
		}
	}

	CalculateLateralAndLongitudinalCosts(m_TrajectoryCosts, rollOuts, totalPaths, currState, m_AllContourPoints, params, carInfo, vehicleState);

	NormalizeCosts(m_TrajectoryCosts);

	int smallestIndex = -1;
	double smallestCost = DBL_MAX;
	double smallestDistance = DBL_MAX;
	double velo_of_next = 0;

	//cout << "Trajectory Costs Log : CurrIndex: " << currIndex << " --------------------- " << endl;
	for(unsigned int ic = 0; ic < m_TrajectoryCosts.size(); ic++)
	{
		//cout << m_TrajectoryCosts.at(ic).ToString();
		if(!m_TrajectoryCosts.at(ic).bBlocked && m_TrajectoryCosts.at(ic).cost < smallestCost)
		{
			smallestCost = m_TrajectoryCosts.at(ic).cost;
			smallestIndex = ic;
		}

		if(m_TrajectoryCosts.at(ic).closest_obj_distance < smallestDistance)
		{
			smallestDistance = m_TrajectoryCosts.at(ic).closest_obj_distance;
			velo_of_next = m_TrajectoryCosts.at(ic).closest_obj_velocity;
		}
	}

	//cout << "Smallest Distance: " <<  smallestDistance << "------------------------------------------------------------- " << endl;

	//All is blocked !
	if(smallestIndex == -1 && m_PrevCostIndex < (int)m_TrajectoryCosts.size())
	{
		bestTrajectory.bBlocked = true;
		bestTrajectory.lane_index = currLaneIndex;
		bestTrajectory.index = currIndex;
		bestTrajectory.closest_obj_distance = smallestDistance;
		bestTrajectory.closest_obj_velocity = velo_of_next;
		//bestTrajectory.index = smallestIndex;
	}
	else if(smallestIndex >= 0)
	{
		bestTrajectory = m_TrajectoryCosts.at(smallestIndex);
		//bestTrajectory.index = smallestIndex;
	}

//	cout << "smallestI: " <<  smallestIndex << ", C_Size: " << m_TrajectoryCosts.size()
//			<< ", LaneI: " << bestTrajectory.lane_index << "TrajI: " << bestTrajectory.index
//			<< ", prevSmalI: " << m_PrevCostIndex << ", distance: " << bestTrajectory.closest_obj_distance
//			<< ", Blocked: " << bestTrajectory.bBlocked
//			<< endl;

	m_PrevCostIndex = smallestIndex;

	return bestTrajectory;

		return true;

	}
	else
		return false;
}

