AisanIntersectionFileReader::AisanIntersectionFileReader(const vector_map_msgs::CrossRoadArray& _inters) : SimpleReaderBase("d", 1)
{
	if(_inters.data.size()==0) return;

	m_min_id = std::numeric_limits<int>::max();

	m_data_list.clear();
	AisanIntersection data;
	int max_id = std::numeric_limits<int>::min();

	for(unsigned int i=0; i < _inters.data.size(); i++)
	{
		ParseNextLine(_inters.data.at(i), data);

		m_data_list.push_back(data);
		if(data.ID < m_min_id)
			m_min_id = data.ID;

		if(data.ID > max_id)
			max_id = data.ID;
	}

	m_data_map.resize(max_id-m_min_id+2);
	for(unsigned int i=0; i < m_data_list.size(); i++)
	{
		m_data_map.at(m_data_list.at(i).ID-m_min_id) = &m_data_list.at(i);
	}
}

void AisanIntersectionFileReader::ParseNextLine(const vector_map_msgs::CrossRoad& _rec, AisanIntersection& data)
{
	data.AID = _rec.aid;
	data.ID = _rec.id;
	data.LinkID = _rec.linkid;
}

AisanIntersectionFileReader::AisanIntersection* AisanIntersectionFileReader::GetDataRowById(int _id)
{
	if(m_data_map.size()==0) return nullptr;

	int index = _id-m_min_id;
	if(index >= 0 && index < m_data_map.size())
	{
		return m_data_map.at(index);
	}
	else
	{
		for(unsigned int i=0; i < m_data_list.size(); i++)
		{
			if(m_data_list.at(i).ID == _id)
			{
				return &m_data_list.at(i);
			}
		}
	}

	return nullptr;
}

bool AisanIntersectionFileReader::ReadNextLine(AisanIntersection& data)
{
	vector<vector<string> > lineData;
	if(ReadSingleLine(lineData))
	{
		if(lineData.size()==0) return false;
		if(lineData.at(0).size() < 3) return false;

		data.ID = strtol(lineData.at(0).at(0).c_str(), NULL, 10);
		data.AID = strtol(lineData.at(0).at(1).c_str(), NULL, 10);
		data.LinkID = strtol(lineData.at(0).at(2).c_str(), NULL, 10);

		return true;

	}
	else
		return false;
}

int AisanIntersectionFileReader::ReadAllData(vector<AisanIntersection>& data_list)
{
	data_list.clear();
	AisanIntersection data;
	//double logTime = 0;
	int count = 0;
	while(ReadNextLine(data))
	{
		data_list.push_back(data);
		count++;
	}
	return count;
}

//StopLine

AisanStopLineFileReader::AisanStopLineFileReader(const vector_map_msgs::StopLineArray& _stopLines) : SimpleReaderBase("d", 1)
{
	if(_stopLines.data.size()==0) return;

	m_min_id = std::numeric_limits<int>::max();

	m_data_list.clear();
	AisanStopLine data;
	int max_id = std::numeric_limits<int>::min();

	for(unsigned int i=0; i < _stopLines.data.size(); i++)
	{
		ParseNextLine(_stopLines.data.at(i), data);

		m_data_list.push_back(data);
		if(data.ID < m_min_id)
			m_min_id = data.ID;

		if(data.ID > max_id)
			max_id = data.ID;
	}

	m_data_map.resize(max_id-m_min_id+2);
	for(unsigned int i=0; i < m_data_list.size(); i++)
	{
		m_data_map.at(m_data_list.at(i).ID-m_min_id) = &m_data_list.at(i);
	}
}

void AisanStopLineFileReader::ParseNextLine(const vector_map_msgs::StopLine& _rec, AisanStopLine& data)
{
	data.ID = _rec.id;
	data.LID = _rec.lid;
	data.LinkID = _rec.linkid;

		sum_part_size += part_size;
		sum_pointer_size += pointer_size;


		if(pt->pid*part_y < pt->numpart[jj]){

			if(pt->pid == 0){
				gettimeofday(&tv_memcpy_start, NULL);
			}


			res = cuMemcpyDtoH((void *)(pointer_dst_tmpIx+(unsigned long long int)(pointer_size*sizeof(int))), (CUdeviceptr)(pointer_tmpIx_dev+(unsigned long long int)(pointer_size*sizeof(int))), part_size*sizeof(int));
			if(res != CUDA_SUCCESS) {
				printf("error pid = %d\n",pt->pid);
				printf("cuMemcpyDtoH(tmpIx) failed: res = %s\n", cuda_response_to_string(res));
				exit(1);
			}

			if(pt->pid == 0){
				gettimeofday(&tv_memcpy_end, NULL);
				tvsub(&tv_memcpy_end, &tv_memcpy_start, &tv);
				time_memcpy += tv.tv_sec * 1000.0 + (float)tv.tv_usec / 1000.0;
			}

		}

		pointer_dst_tmpIx += (unsigned long long int)(move_size * sizeof(int));
		pointer_tmpIx_dev += (unsigned long long int)(move_size * sizeof(int));

		part_size = 0;
		pointer_size = 0;
		move_size = 0;

	}

}


/* downloads tmpIy from GPU */

sum_part_size = 0;
sum_pointer_size = 0;
part_size = 0;
pointer_size = 0;
part_y = 0;
move_size = 0;
start_kk = 0;
end_kk = 0;
part_end_kk = 0;
unsigned long long int pointer_dst_tmpIy = (unsigned long long int)pt->dst_tmpIy;
unsigned long long int pointer_tmpIy_dev = (unsigned long long int)tmpIy_dev[pt->pid];


for(int L=0; L<(pt->L_MAX-pt->interval); L++) {

	/**************************************************************************/
	/* loop condition */
	if( (pt->FSIZE[(L+pt->interval)*2]+2*pt->pady < pt->max_Y) || (pt->FSIZE[(L+pt->interval)*2+1]+2*pt->padx < pt->max_X) )
	{
		continue;
	}
	/* loop conditon */
	/**************************************************************************/


	for(int jj=0; jj<pt->NoC; jj++) {

		part_y = pt->numpart[jj] / device_num;
		if(pt->numpart[jj]%device_num != 0){
			part_y++;
		}

		start_kk = part_y * pt->pid;
		end_kk = part_y * (pt->pid + 1);

		if(end_kk > pt->numpart[jj]){
			end_kk = pt->numpart[jj];
		}

		if(pt->pid > 0){
			part_end_kk = part_y * pt->pid;
		}

		for(int kk=0; kk<pt->numpart[jj]; kk++) {

			int PIDX = pt->PIDX_array[L][jj][kk];
			int dims0 = pt->size_array[L][PIDX*2];
			int dims1 = pt->size_array[L][PIDX*2+1];
			if(start_kk <= kk && kk < end_kk){
				part_size += dims0 * dims1;
			}
			if(pt->pid > 0){
				if(0 <= kk && kk < part_end_kk){
					pointer_size += dims0 * dims1;
				}
			}
			move_size += dims0 * dims1;
		}

		sum_part_size += part_size;
		sum_pointer_size += pointer_size;

		if(pt->pid*part_y < pt->numpart[jj]){

			if(pt->pid == 0){
				gettimeofday(&tv_memcpy_start, NULL);
			}

			res = cuMemcpyDtoH((void *)(pointer_dst_tmpIy+(unsigned long long int)(pointer_size*sizeof(int))), (CUdeviceptr)(pointer_tmpIy_dev+(unsigned long long int)(pointer_size*sizeof(int))), part_size*sizeof(int));
			if(res != CUDA_SUCCESS) {
				printf("error pid = %d\n",pt->pid);
				printf("cuMemcpyDtoH(tmpIy) failed: res = %s\n", cuda_response_to_string(res));
				exit(1);
			}

			if(pt->pid == 0){
				gettimeofday(&tv_memcpy_end, NULL);
				tvsub(&tv_memcpy_end, &tv_memcpy_start, &tv);
				time_memcpy += tv.tv_sec * 1000.0 + (float)tv.tv_usec / 1000.0;
			}

		}

		pointer_dst_tmpIy += (unsigned long long int)(move_size * sizeof(int));
		pointer_tmpIy_dev += (unsigned long long int)(move_size * sizeof(int));

		part_size = 0;
		pointer_size = 0;
		move_size = 0;

	virtual BehaviorStateMachine* GetNextState();

};

